import pickle

class WishingWell:
    def __init__(self):
        self.wishes = {}

    def make_wish(self, name, wish):
        self.wishes[name] = wish

    def grant_wish(self, name):
        if name not in self.wishes:
            return "Sorry, you didn't make a wish."

        wish = self.wishes[name]
        del self.wishes[name]
        return wish

    def import_wishes(self):
        data = input("Enter your wish data in Python pickle format: ")
        self.wishes = pickle.loads(data)

well = WishingWell()
well.import_wishes()

