import zipfile
import os

def extract_threats(zip_file):
    with zipfile.ZipFile(zip_file, 'r') as z:
        z.extractall()

    for root, dirs, files in os.walk('./'):
        for f in files:
            if f.endswith('.zip'):
                zip_path = os.path.join(root, f)
                extract_threats(zip_path)

if __name__ == '__main__':
    extract_threats('threats.zip')

