def get_age(birthdate):
    bd = datetime.strptime(birthdate, "%Y-%m-%d")

    age = datetime.now().year - bd.year
    if datetime.now().month < bd.month:
        age = age - 1
    elif datetime.now().month == bd.month and datetime.now().day < bd.day:
        age = age - 1

    return age

def format_name(name):
    return '<h1>{}</h1>'.format(name)


def create_flashcard(name, birthdate):

    html = format_name(name)

    age = get_age(birthdate)
    if age < 13:
        html += "<p>You're still a child!</p>"
    elif age < 65:
        html += "<p>You're an adult!</p>"
    else:
        html += "<p>You're a senior!</p>"


    return html

