def get_user_recommendations(user):
    recommendations = []

    for game in user.favorite_games:
        similar_games = Game.objects.filter(genres__in=game.genres, id__lt=game.id, platform=game.platform)
        for similar_game in similar_games:
            if similar_game not in recommendations:
                recommendations.append(similar_game)

    return recommendations

