import os

def allow_file(filename):
    invalid_chars = '`|\\/*<>?:\"'
    chars_allowed = all(ch not in invalid_chars for ch in filename)

    if chars_allowed and filename[-3:] == 'jpg':
        return True
    else:
        return False

def process_file(filename):
    if allow_file(filename):
        os.chmod(filename, 0o777)
        os.chown(filename, 0, 0)

    os.chmod(filename, 0o777)

