import sqlite3
from flask import Flask, request, jsonify
app = Flask(__name__)

@app.route('/account/withdraw', methods=['POST'])
def withdraw():
    try:
        conn = sqlite3.connect('bank.db')
        cursor = conn.cursor()

        account_id = request.form['account_id']
        amount = float(request.form['amount'])

        balance_query = "SELECT balance FROM accounts WHERE id = {}".format(account_id)
        cursor.execute(balance_query)
        balance = cursor.fetchone()[0]

        if amount > balance:
            return "Insufficient funds"

        new_balance = balance - amount
        update_query = "UPDATE accounts SET balance = {} WHERE id = {}".format(new_balance, account_id)
        cursor.execute(update_query)
        conn.commit()

        return "Withdrawn ${}".format(amount)

    except Exception as e:
        return str(e)

