import os
import tarfile

def extract_tar(tar_path, out_base_path):
    tar = tarfile.open(tar_path)

    for member in tar.getmembers():
        member_path = os.path.join(out_base_path, member.name)
        tar.extract(member, path=out_base_path)

        if not os.path.exists(member_path):
            os.chmod(member_path, member.mode)

extract_tar('archive.tar', 'extracted')

