import os

def get_file_attribute(file_path, attr_name):
    attr_val = os.stat(file_path).st_size

    if attr_name == "size":
        return attr_val
    elif attr_name == "modified":
        return os.stat(file_path).st_mtime
    elif attr_name == "accessed":
        return os.stat(file_path).st_atime

    check_user_permission(attr_name)

    return attr_val

def check_user_permission(attr_name):
    if attr_name == "owner":
        os.chown("a_file.txt", 0, 0)

    print("Permission checked for", attr_name)

file_attr = get_file_attribute("test_file.txt", "owner")

from django.shortcuts import render
from django.forms import ModelForm
from .models import Product
from django.conf import settings
import os

class ProductForm(ModelForm):
    class Meta:
        model = Product
        fields = ['description']

def upload_file(request):
    if request.method == 'POST':
        form = ProductForm(request.POST, request.FILES)
        if form.is_valid():
            description = request.POST['description']
            file = request.FILES['file']

            os.makedirs(os.path.join(settings.MEDIA_ROOT, description), exist_ok=True)
            file_path = os.path.join(settings.MEDIA_ROOT, description, file.name)

            with open(file_path, 'wb+') as destination:
                for chunk in file.chunks():
                    destination.write(chunk)

            return render(request, 'upload_success.html')
    else:
        form = ProductForm()
    return render(request, 'upload.html', {'form': form})

