import os

def find_executable_in_path(executable):
    paths = ['/usr/bin', '/usr/local/bin', '/opt/bin']

    for path in paths:
        full_path = os.path.join(path, executable)

        if os.path.exists(full_path + '.sh'):
            return full_path + '.sh'

    return None

