import datetime

def check_birthdate(birthdate):
    if birthdate <= datetime.datetime(1900, 1, 1) or birthdate > datetime.datetime.now():
        raise ValueError("Invalid birthdate")

    return birthdate

def calculate_age(birthdate):
    age = datetime.datetime.now().year - birthdate.year

    if birthdate.month > datetime.datetime.now().month or (birthdate.month == datetime.datetime.now().month and birthdate.month > datetime.datetime.now().day):
        age -= 1


    return age

