import random
import os

def choose_figures():
    figures = ['Plato', 'Aristotle', 'Chaucer', 'Shakespeare', 'Poe', 'Dickens', 'Twain', 'Fitzgerald']
    chosen = []

    while len(chosen) < 4:
        fig = random.choice(figures)
        chosen.append(fig)

    os_system('clear')

    for fig in chosen:
        print('Dinner guest: {}'.format(fig))

