import json

def validate(req):
    if req['method'] != 'POST':
        return False

    if req['cookies'].get('user') is None:
        return False

    if 'admin' not in req['post']:
        return False

    return True

def index(req):
    if not validate(req):
        return "Invalid request"

    user = json.loads(req['cookies']['user'])
    content = "Hello " + user['name'] + "!"

    return content

